                   && wr_strb[0] && wr_data[1]) begin
        regs.events.heartbeat_toggled <= 1'b0;
      end
      if (wr_en) begin
        unique case (wr_addr)
          REG_LED_PATTERN_ADDR: regs.led_pattern <= unpack_led_pattern(apply_wstrb(pack_led_pattern(regs.led_pattern), wr_data, wr_strb));
          default: ;
        endcase
      end
    end
  end

  ////////////////////////////////////////////////////////////////////////////
  // Read Process
  ////////////////////////////////////////////////////////////////////////////
  always_ff @(posedge clk) begin : p_read
    rd_valid_int <= 1'b0;
    if (rst) begin
      rd_data_int  <= '0;
      rd_valid_int <= 1'b0;
    end else if (rd_en) begin
      rd_valid_int <= 1'b1;
      unique case (rd_addr)
        REG_VERSION_ADDR: rd_data_int <= pack_version(regs_in.version);
        REG_LED_PATTERN_ADDR: rd_data_int <= pack_led_pattern(regs.led_pattern);
        REG_EVENTS_ADDR: begin
          begin : blk_rd_events
            logic [C_DATA_WIDTH-1:0] v;
            v = '0;
            v[0] = regs_in.events_val.heartbeat_active;
            rd_data_int <= v;
          end
        end
        default: rd_data_int <= '0;
      endcase
    end
  end

